<script setup>import {ref,computed} from 'vue';import AppShell from '../../components/AppShell.vue';import StatusPill from '../../components/StatusPill.vue';import {suppliers} from '../../api/mock';const keyword=ref(''),tab=ref('全部供应商');const filtered=computed(()=>suppliers.filter(s=>(tab.value==='全部供应商'||(tab.value==='准入审核'&&s.status==='准入审核')||(tab.value==='风险关注'&&s.risk!=='低'))&&(s.name.includes(keyword.value)||s.code.includes(keyword.value))))</script>
<template><AppShell mode="admin"><div class="page-head"><div><span class="breadcrumb">供应商管理 / 供应商库</span><h1>供应商库</h1><p>统一维护准入资质、合作状态、绩效分级与风险信息。</p></div><button class="primary">+ 邀请供应商</button></div><section class="panel list-panel"><div class="toolbar"><div class="tabs"><button v-for="t in ['全部供应商','准入审核','风险关注']" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}<em>{{t==='全部供应商'?128:t==='准入审核'?6:4}}</em></button></div><div class="filters"><input v-model="keyword" placeholder="搜索供应商名称或编码"/><select><option>全部品类</option><option>工业连接器</option><option>电子元器件</option></select><button class="secondary">筛选</button></div></div><table class="supplier-table"><thead><tr><th><input type="checkbox"/></th><th>供应商</th><th>主供品类</th><th>采购负责人</th><th>合作状态</th><th>绩效等级</th><th>综合得分</th><th>准交率</th><th>风险</th><th></th></tr></thead><tbody><tr v-for="s in filtered" :key="s.code"><td><input type="checkbox"/></td><td><div class="supplier-name"><span>{{s.name.slice(0,1)}}</span><div><b>{{s.name}}</b><small>{{s.code}}</small></div></div></td><td>{{s.category}}</td><td>{{s.owner}}</td><td><StatusPill :text="s.status"/></td><td><b class="grade">{{s.grade}}</b></td><td>{{s.score}}</td><td>{{s.delivery}}</td><td><StatusPill :text="s.risk"/></td><td><button class="more">•••</button></td></tr></tbody></table><div class="pagination"><span>共 128 条记录</span><div><button>‹</button><button class="active">1</button><button>2</button><button>3</button><button>…</button><button>13</button><button>›</button></div></div></section></AppShell></template>
